-- Doctors and nurses with their clinic cost centre and total salary. Output per row: org|job|staff|name|salary. Page with ROW_NUMBER if over 200 rows.
-- Job ids must match config/jobs_depts.json (doctor_jobs and nurse_jobs). The doctor to nurse link is the same ORGANIZATION_NO because RC_CLINICAL_ENTITIES_NURSE is empty.
SELECT x.s FROM (SELECT ROW_NUMBER() OVER (ORDER BY t.ORGANIZATION_NO, t.STAFF_JOB_ID, c.STAFF_ID) rn, t.ORGANIZATION_NO||'|'||t.STAFF_JOB_ID||'|'||c.STAFF_ID||'|'||TRIM(m.STAFF_NAME_1_S||' '||m.STAFF_NAME_2_S||' '||m.STAFF_NAME_F_S)||'|'||(NVL((SELECT MAX(s.BASIC_SALARY) FROM {P}PR_STAFF_DEFAULT_SALARY_M s WHERE s.STAFF_ID=c.STAFF_ID AND s.DATE_END IS NULL),0)+NVL((SELECT SUM(d.SALARY_ITEM_AMOUNT) FROM {P}PR_STAFF_DEFAULT_SALARY_D d WHERE d.STAFF_ID=c.STAFF_ID AND d.DATE_START=(SELECT MAX(s2.DATE_START) FROM {P}PR_STAFF_DEFAULT_SALARY_M s2 WHERE s2.STAFF_ID=c.STAFF_ID AND s2.DATE_END IS NULL)),0)) s FROM {P}PS_STAFF_CONTRACT c JOIN {P}STAFF_MASTER m ON m.STAFF_ID=c.STAFF_ID JOIN {P}PS_STAFF_INTERNAL_TRANSFERS t ON t.STAFF_ID=c.STAFF_ID AND t.CURRENT_JOB='Y' WHERE c.STATUS='A' AND c.CURRENT_CONTRACT='Y' AND t.STAFF_JOB_ID IN ('098','101','15','150','152','153','154','155','156','157','158','159','160','162','170','171','173','174','192','53','61','102','N','223')) x WHERE x.rn BETWEEN 1 AND 200 ORDER BY x.rn
